import { test, expect } from '@playwright/test';

test.describe('Form Submission Button Disabled Until All Required Fields Are Filled', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should disable submit button when required fields are empty', async ({ page }) => {
    // Verify submit button is disabled initially
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Verify required fields are visible
    const firstNameInput = page.getByLabel(/first name/i);
    const lastNameInput = page.getByLabel(/last name/i);
    const emailInput = page.getByLabel(/email/i);
    const phoneInput = page.getByLabel(/phone number/i);

    await expect(firstNameInput).toBeVisible();
    await expect(lastNameInput).toBeVisible();
    await expect(emailInput).toBeVisible();
    await expect(phoneInput).toBeVisible();

    // Attempt to submit with empty fields
    await submitButton.click();
    await expect(submitButton).toBeDisabled();
    await expect(page).toHaveURL(/.*form/);
  });

  test('should enable submit button when all required fields are filled', async ({ page }) => {
    // Fill in all required fields
    const firstNameInput = page.getByLabel(/first name/i);
    const lastNameInput = page.getByLabel(/last name/i);
    const emailInput = page.getByLabel(/email/i);
    const phoneInput = page.getByLabel(/phone number/i);

    await firstNameInput.fill('John');
    await lastNameInput.fill('Doe');
    await emailInput.fill('john.doe@example.com');
    await phoneInput.fill('555-123-467');

    // Verify submit button is now enabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).not.toBeDisabled();

    // Submit the form
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/form submitted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify form is cleared
    await expect(firstNameInput).toHaveValue('');
    await expect(lastNameInput).toHaveValue('');
    await expect(emailInput).toHaveValue('');
    await expect(phoneInput).toHaveValue('');
  });
});
